INSERT INTO parks (name, lat, lon, region) SELECT 'Lotte World Adventure', 37.5111, 127.0982, 'South Korea' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Lotte World Adventure');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Atlantis Adventure', 'Lotte World Adventure', 'Steel', 'Intamin', 'Intamin Water Coaster', 72.2, 46.6, 2198.1, 0, 108, 2003, '2003-10-26', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Atlantis Adventure' AND park = 'Lotte World Adventure');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Atlantis Adventure' AND c.park = 'Lotte World Adventure' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
